static int read_all_fd(int fd, unsigned char **out, size_t *out_length)
{
    struct stat st;
    unsigned char *buffer;
    size_t length = 0, capacity;

    if (fstat(fd, &st) < 0 || st.st_size < 0)
        return -1;
    capacity = st.st_size ? (size_t)st.st_size + 1 : 8192;
    buffer = malloc(capacity);
    if (!buffer)
        return -1;
    if (lseek(fd, 0, SEEK_SET) < 0 && errno != ESPIPE) {
        free(buffer);
        return -1;
    }
    for (;;) {
        ssize_t n;
        if (length + 1 == capacity) {
            unsigned char *grown;
            capacity *= 2;
            grown = realloc(buffer, capacity);
            if (!grown) {
                free(buffer);
                return -1;
            }
            buffer = grown;
        }
        n = read(fd, buffer + length, capacity - length - 1);
        if (n < 0) {
            free(buffer);
            return -1;
        }
        if (n == 0)
            break;
        length += (size_t)n;
    }
    buffer[length] = 0;
    *out = buffer;
    *out_length = length;
    return 0;
}

